"""Brute-force solvers for Clique and SAT, written from the definitions."""

from itertools import combinations


def clique_solve(instance):
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]

    if k <= 0:
        return True
    if k > n:
        return False

    adjacent = set()
    for u, v in edges:
        adjacent.add((u, v))
        adjacent.add((v, u))

    # A clique of size >= k exists iff one of size exactly k exists.
    for subset in combinations(range(n), k):
        if all((u, v) in adjacent for u, v in combinations(subset, 2)):
            return True
    return False


def sat_solve(instance):
    num_vars = instance["num_vars"]
    clauses = instance["clauses"]

    for mask in range(1 << num_vars):
        def value(lit):
            var = abs(lit)
            truth = bool((mask >> (var - 1)) & 1)
            return truth if lit > 0 else not truth

        if all(any(value(lit) for lit in clause) for clause in clauses):
            return True
    return False
EOF
