"""Brute-force / DPLL solvers for Clique and SAT, from the definitions."""

from itertools import combinations


def clique_solve(instance):
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]

    if k <= 0:
        return True
    if k > n:
        return False

    adjacent = set()
    for u, v in edges:
        adjacent.add((u, v))
        adjacent.add((v, u))

    # A clique of size >= k exists iff one of size exactly k exists.
    for subset in combinations(range(n), k):
        if all((u, v) in adjacent for u, v in combinations(subset, 2)):
            return True
    return False


def sat_solve(instance):
    """DPLL with unit propagation; correct for any CNF."""
    num_vars = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]

    def dpll(clauses, assignment):
        # Simplify under current assignment; detect empty clause.
        simplified = []
        for clause in clauses:
            new_clause = []
            satisfied = False
            for lit in clause:
                var = abs(lit)
                if var in assignment:
                    val = assignment[var]
                    if (lit > 0) == val:
                        satisfied = True
                        break
                else:
                    new_clause.append(lit)
            if satisfied:
                continue
            if not new_clause:
                return False
            simplified.append(new_clause)

        if not simplified:
            return True

        # Unit propagation.
        for clause in simplified:
            if len(clause) == 1:
                lit = clause[0]
                var = abs(lit)
                val = lit > 0
                if var in assignment and assignment[var] != val:
                    return False
                new_assignment = dict(assignment)
                new_assignment[var] = val
                return dpll(simplified, new_assignment)

        # Choose a variable.
        lit = simplified[0][0]
        var = abs(lit)
        for val in (True, False):
            new_assignment = dict(assignment)
            new_assignment[var] = val
            if dpll(simplified, new_assignment):
                return True
        return False

    return dpll(clauses, {})
